import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Questionnaire.css";

function Questionnaire({ onNext }) {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    incomeStability: "",
    savingHabit: "",
    majorExpense: "",
    riskLevel: "",
    expenseControl: ""
  });

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleContinue = () => {
    if (typeof onNext === "function") {
      onNext(formData);
    }
    navigate("/spending-priority");
  };

  return (
    <div className="questionnaire-container">
      <div className="questionnaire-card">
        <h2 className="questionnaire-title">Financial Questionnaire</h2>

        <div className="form-group">
          <label className="form-label">Income Stability</label>
          <select
            className="form-select"
            name="incomeStability"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Stable</option>
            <option>Somewhat Stable</option>
            <option>Unstable</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Saving Habit</label>
          <select
            className="form-select"
            name="savingHabit"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Regularly</option>
            <option>Sometimes</option>
            <option>Rarely</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Major Expense</label>
          <select
            className="form-select"
            name="majorExpense"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Food & Groceries</option>
            <option>Bills</option>
            <option>Shopping</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Risk Level</label>
          <select
            className="form-select"
            name="riskLevel"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Low</option>
            <option>Medium</option>
            <option>High</option>
          </select>
        </div>

        <div className="form-group">
          <label className="form-label">Expense Control</label>
          <select
            className="form-select"
            name="expenseControl"
            onChange={handleChange}
          >
            <option value="">Select</option>
            <option>Good</option>
            <option>Average</option>
            <option>Poor</option>
          </select>
        </div>

        <button className="next-button" onClick={handleContinue}>
          Continue
        </button>
      </div>
    </div>
  );
}

export default Questionnaire;
